// The cat, traced from pictures drawn for this project and placed where the
// poses expect them. Generated: edit the poses in cats.ts, not these shapes.
//
// Sitting and asleep, every coat shares one drawing: one outline for each part
// the poses move, the fur lines, ears, face and whiskers. A coat only adds its
// colours and where its white, orange and dark fur lie, in patches trimmed to
// that outline, and a pointed coat its soft darker points.
export type Eye = { cx: number; cy: number; rx: number; ry: number }
export type CushionEye = { cx: number; cy: number; width: number }
export type CoatName = 'calico' | 'tuxedo' | 'siamese'
export type Fur = 'white' | 'orange' | 'dark'
export type Part = 'tail' | 'body' | 'head'
/** A fur line, and the fur it lies on in each patched coat; in any other, white. */
export type FurLine = { d: string; on: Partial<Record<CoatName, Fur>> }
export type Patches = Partial<Record<Fur, string>>
type Drawing = {
  pink: string
  whiskers: { colour: string; shapes: string[] }
}
export type Colours = {
  white: string
  dark: string
  orange?: string
  line: string
  tickLight: string
  tickDark?: string
  pink: string
  ink: string
}
/** What a coat brings to a drawing: its colours and where its fur lies. */
export type CoatDrawing<Fill extends string> = { colours: Colours; patches: Record<Fill, Patches> }

